package com.nigson.acceptance.cart;
import com.nigson.commerce.security.*;
import com.nigson.shared.events.EventCodec;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;
import java.time.*;
import java.net.*;
import java.net.http.*;
import static org.assertj.core.api.Assertions.*;
public final class CartHttpAcceptance {
 private CartHttpAcceptance(){}
 public static void run(ConfigurableApplicationContext app,HttpClient http,String base,com.nigson.acceptance.provider.JobHttpAcceptance.Fixture identity)throws Exception{if(System.getenv("NIGSON_TEST_CART")==null)return;var sessions=app.getBean(JdbcSessionTrust.class);var cookies=new ArrayList<String>();var tokens=new ArrayList<String>();try(var fixture=new CartFixture(app.getBean(JdbcTemplate.class),app.getBean(org.springframework.transaction.PlatformTransactionManager.class))){var f=fixture.f;f.retail();for(UUID party:List.of(f.customer.party(),f.finance.party())){String issuer=f.jdbc.queryForObject("SELECT identity_issuer FROM commerce.party WHERE id=?",String.class,party);var flow=sessions.begin("/account");sessions.consume(flow.sessionId(),flow.flow().state());String csrf=JdbcSessionTrust.opaque();tokens.add(csrf);String session=sessions.authenticate(flow.sessionId(),new SessionRecord(1,party,issuer,party.toString(),Instant.now(),Instant.now(),"synthetic-access","synthetic-refresh",Instant.now().plusSeconds(300),csrf,SessionRecord.TokenState.READY));cookies.add("__Host-nigson-session="+session);}String root=base+"/api/v1/carts",cart=root+"/"+f.cart,line=cart+"/lines/"+f.sku,input="{\"marketId\":\""+f.market+"\"}";assertThat(send(http,HttpRequest.newBuilder(URI.create(cart)).GET()).statusCode()).isEqualTo(401);assertThat(send(http,HttpRequest.newBuilder(URI.create(cart)).header("Authorization","Bearer browser-token").GET()).statusCode()).isEqualTo(401);var existing=send(http,command(root,"POST",cookies.getFirst(),tokens.getFirst(),"create",input,null));assertThat(existing.statusCode()).as("create: %s",existing.body()).isEqualTo(201);assertThat(EventCodec.JSON.readTree(existing.body()).get("id").asString()).isEqualTo(f.cart.toString());assertThat(existing.headers().firstValue("ETag")).hasValue("\"0\"");assertThat(existing.headers().firstValue("Cache-Control")).hasValue("no-store");assertThat(send(http,HttpRequest.newBuilder(URI.create(cart)).header("Cookie",cookies.get(1)).GET()).statusCode()).isEqualTo(404);assertThat(send(http,command(line,"PUT",cookies.getFirst(),"wrong","bad-csrf","{\"quantity\":\"3\"}",0L)).statusCode()).isEqualTo(401);assertThat(send(http,command(line,"PUT",cookies.getFirst(),tokens.getFirst(),"zero","{\"quantity\":\"0\"}",0L)).statusCode()).isEqualTo(400);assertThat(send(http,command(line,"PUT",cookies.getFirst(),tokens.getFirst(),"unknown","{\"quantity\":\"3\",\"price\":\"0\"}",0L)).statusCode()).isEqualTo(400);var changed=send(http,command(line,"PUT",cookies.getFirst(),tokens.getFirst(),"put","{\"quantity\":\"3\"}",0L));assertThat(changed.statusCode()).as("put: %s",changed.body()).isEqualTo(200);assertThat(changed.headers().firstValue("ETag")).hasValue("\"1\"");assertThat(send(http,command(line,"PUT",cookies.getFirst(),tokens.getFirst(),"put","{\"quantity\":\"3\"}",0L)).body()).isEqualTo(changed.body());assertThat(send(http,command(line,"PUT",cookies.getFirst(),tokens.getFirst(),"stale","{\"quantity\":\"4\"}",0L)).statusCode()).isEqualTo(412);var current=send(http,HttpRequest.newBuilder(URI.create(cart)).header("Cookie",cookies.getFirst()).GET());assertThat(current.body()).isEqualTo(changed.body());assertThat(send(http,HttpRequest.newBuilder(URI.create(cart+"?owner="+f.customer.party())).header("Cookie",cookies.getFirst()).GET()).statusCode()).isEqualTo(400);var removed=send(http,command(line,"DELETE",cookies.getFirst(),tokens.getFirst(),"delete",null,1L));assertThat(removed.statusCode()).as("delete: %s",removed.body()).isEqualTo(204);assertThat(removed.body()).isEmpty();assertThat(removed.headers().firstValue("ETag")).hasValue("\"2\"");assertThat(send(http,command(line,"DELETE",cookies.getFirst(),tokens.getFirst(),"delete",null,1L)).statusCode()).isEqualTo(204);String recovery=base+"/internal/v1/cart-recovery/"+f.cart+"/eligibility",recoveryToken=identity.workload("recovery.read","nigson-integration","nigson-commerce");var add=send(http,command(line,"PUT",cookies.getFirst(),tokens.getFirst(),"recovery-line","{\"quantity\":\"3\"}",2L));assertThat(add.statusCode()).isEqualTo(200);f.jdbc.update("UPDATE commerce.cart SET last_activity_at=now()-interval '25 hours' WHERE id=?",f.cart);var recoveryRequest=privateRequest(recovery,recoveryToken).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString("{}"));var eligible=send(http,recoveryRequest);assertThat(eligible.statusCode()).as("API-159: %s",eligible.body()).isEqualTo(200);assertThat(eligible.headers().firstValue("Cache-Control")).hasValue("no-store");var body=EventCodec.JSON.readTree(eligible.body());assertThat(body.propertyNames()).containsExactlyInAnyOrder("eligible","partyId","cartLink");assertThat(body.path("eligible").asBoolean()).isTrue();assertThat(body.path("partyId").asString()).isEqualTo(f.customer.party().toString());assertThat(body.path("cartLink").isNull()).isTrue();assertThat(send(http,privateRequest(recovery,identity.workload("notification.read","nigson-integration","nigson-commerce")).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString("{}"))).statusCode()).isEqualTo(401);assertThat(send(http,privateRequest(recovery,identity.workload("recovery.read","nigson-experience","nigson-commerce")).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString("{}"))).statusCode()).isEqualTo(401);assertThat(send(http,privateRequest(recovery+"?include=customer",recoveryToken).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString("{}"))).statusCode()).isEqualTo(400);assertThat(send(http,privateRequest(recovery,recoveryToken).header("X-Nigson-Actor","invalid").header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString("{}"))).statusCode()).isEqualTo(401);assertThat(send(http,privateRequest(recovery,recoveryToken).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString("{\"send\":true}"))).statusCode()).isEqualTo(400);assertThat(send(http,privateRequest(recovery,recoveryToken).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString("{}"))).body()).isEqualTo(eligible.body());assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.abandoned_cart_candidate WHERE cart_id=?",Integer.class,f.cart)).isEqualTo(1);var registry=app.getBean(io.micrometer.core.instrument.MeterRegistry.class);assertThat(registry.get("nigson.cart.commands").tag("operation","SET").counter().count()).isEqualTo(2);assertThat(registry.get("nigson.cart.commands").tag("operation","REMOVE").counter().count()).isEqualTo(1);}finally{for(String cookie:cookies)sessions.logout(cookie.substring(cookie.indexOf('=')+1));}}
 private static HttpRequest.Builder command(String uri,String method,String cookie,String csrf,String key,String body,Long version){var request=HttpRequest.newBuilder(URI.create(uri)).header("Cookie",cookie).header("X-CSRF-TOKEN",csrf).header("Idempotency-Key",key);if(version!=null)request.header("If-Match","\""+version+"\"");if(body!=null)request.header("Content-Type","application/json");return request.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body));}
 private static HttpRequest.Builder privateRequest(String uri,String token){return HttpRequest.newBuilder(URI.create(uri)).header("Authorization","Bearer "+token).header("X-Correlation-ID",UUID.randomUUID().toString());}
 private static HttpResponse<String> send(HttpClient http,HttpRequest.Builder request)throws Exception{return http.send(request.timeout(Duration.ofSeconds(10)).build(),HttpResponse.BodyHandlers.ofString());}
}
